mapper.select:
SELECT requested.wind_code ,CASE WHEN si.security_source = 'temporary' THEN t.temp_security_market ELSE si.market END AS rawMarketCode ,si.security_source FROM (
SELECT CAST(#{code} AS CHAR(100)) AS wind_code
) requested LEFT JOIN rrs_securityinfo si ON si.wind_code = requested.wind_code LEFT JOIN rrs_temp_security_code t ON t.temp_security_code = requested.wind_code AND si.security_source = 'temporary'
